import{_ as t,o as a,c as n,a2 as r}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Legacy and Modern Combat","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/combat/legacy-and-modern.md","filePath":"en/guide/combat/legacy-and-modern.md"}'),d={name:"en/guide/combat/legacy-and-modern.md"};function i(o,e,l,s,c,h){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="legacy-and-modern-combat" tabindex="-1">Legacy and Modern Combat <a class="header-anchor" href="#legacy-and-modern-combat" aria-label="Permalink to &quot;Legacy and Modern Combat&quot;">​</a></h1><p><strong>Status:</strong> Proposed · New design not established as playable.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Both modes select a target and share weapon numbers, costs and action phases.</li><li>Legacy uses automatic cadence; Modern lets you initiate available actions.</li><li>Modern is the preferred experimental direction; Legacy remains a supported design alternative.</li></ul><p>Both modes start with a selected target and share base weapon numbers. Modern changes when you initiate an action; it does not grant hidden damage.</p><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Legacy</th><th>Modern</th></tr></thead><tbody><tr><td>Target selection</td><td>Select first</td><td>Select first</td></tr><tr><td>Basic attack</td><td>Automatic cadence</td><td>Input starts available action</td></tr><tr><td>Offensive SA</td><td>Queue next valid swing</td><td>Trigger available action</td></tr><tr><td>Defensive SA</td><td>Manual when available</td><td>Manual when available</td></tr><tr><td>Stamina</td><td>Shared base costs</td><td>Same; rushing adds costs</td></tr><tr><td>Recovery</td><td>All phases must finish</td><td>All phases must finish</td></tr><tr><td>Reach</td><td>Weapon/action footprint</td><td>Same footprint</td></tr><tr><td>Flow</td><td>No Flow layer</td><td>Steady rhythm can earn small benefits</td></tr><tr><td>Timing control</td><td>Anticipate the next swing</td><td>Choose when to commit</td></tr><tr><td>Beginner experience</td><td>Less input pressure</td><td>More direct timing responsibility</td></tr></tbody></table><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ul><li>“Immediate” means initiation, not instant impact or cancellation of recovery.</li><li>Legacy remains the proposed accessibility/familiarity alternative.</li><li>Modern is the preferred experimental direction, not an Accepted replacement.</li><li>Basic archery has no mandatory timing game. Modern controls release; stationary aim can help. Legacy releases on cadence.</li><li>Selected ranged SAs may share a timing challenge in both modes; bows have no new numbers here.</li></ul><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>Queue a Longsword Thrust in Legacy for the next valid swing, or trigger it yourself in Modern when available. Either way, you pay its stamina and finish its phases.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/combat/numeric-prototype.html">Numeric profile</a> · <a href="/Syrolands-Public/en/guide/combat/flow.html">Flow</a> · <a href="/Syrolands-Public/en/game-design/combat/legacy-and-modern.html">Full design</a></p>',13)])])}const u=t(d,[["render",i]]);export{p as __pageData,u as default};
